// Fresh verifier's caller-boundary regression. Run after the canonical inputs
// have been generated by make verify-E6-T12g6m. Expected values are literal
// source/geometry admission rules, never GPU outputs or generated expressions.
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import {createVirglShaderBridge} from '../index.mjs';
const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'../../..');
const originals=path.join(root,'evidence/virgl-workload-inventory/captures/es2gears/shaders');
const vertexText=fs.readFileSync(path.join(originals,'7bf4d0d0f981a9feb958d6595302b15d564fc846e6d5ee71874f0921b31e613e.tgsi'),'utf8');
const fragmentText=fs.readFileSync(path.join(originals,'92cb866af48f952b719c54959a439c7330333c6d32897430bc3d4a0a2f63bfba.tgsi'),'utf8');
const geometry=new Uint8Array(fs.readFileSync(path.join(root,'target/evidence/virgl-92cb-raster/geometry.bin')));
const drawState={viewportX:0,viewportY:0,viewportWidth:1024,viewportHeight:768,samples:0,colorFormat:34836,mode:5,first:0,count:4};
const bridge=await createVirglShaderBridge();
const request=bank=>({vertexText,fragmentText,geometry:new Uint8Array(geometry),bank,drawState:{...drawState}});
const records=[],prefixRecords=[];
function reject(name,call){const result=bridge.translateOriginal92cbComplete(call);assert.equal(result.ok,false,name);assert.equal(result.error.code,'invalid-input',name);assert.equal(Object.hasOwn(result,'vertex'),false,name);assert.equal(Object.hasOwn(result,'fragment'),false,name);records.push({name,code:result.error.code});}
const seeds=[0x72657269,0xa55a091f,0x01020304];
for(const bank of [0,1,2]){
 const baseline=bridge.translateOriginal92cbComplete(request(bank));assert.equal(baseline.ok,true);assert.equal(baseline.private92cbComplete.bank,bank);assert.equal(baseline.private92cbComplete.productionDrawAuthority,false);
 const prefix=bridge.translateOriginal92cbFirstPower(request(bank));assert.equal(prefix.ok,true);assert.equal(prefix.private92cbFirstPower.bank,bank);assert.equal(prefix.private92cbFirstPower.productionDrawAuthority,false);assert.equal(Object.hasOwn(prefix,'private92cbComplete'),false);assert.equal(prefix.fragment.glsl.includes('private_power_domain'),false);prefixRecords.push({bank,kind:prefix.private92cbFirstPower.kind,vertexBytes:prefix.vertex.glsl.length,fragmentBytes:prefix.fragment.glsl.length});
 const frozen=request(bank);Object.freeze(frozen.drawState);Object.freeze(frozen);assert.deepEqual(bridge.translateOriginal92cbComplete(frozen),baseline);
 const shared=request(bank);shared.geometry=new Uint8Array(new SharedArrayBuffer(geometry.length));shared.geometry.set(geometry);assert.deepEqual(bridge.translateOriginal92cbComplete(shared),baseline,'shared caller storage is snapshotted');
 const late=request(bank);let mutations=0;late.drawState=new Proxy(late.drawState,{getOwnPropertyDescriptor(target,key){if(!mutations++){late.geometry[72+bank*656+64+24*4]^=1;late.vertexText+='\n';late.bank=(bank+1)%3;}return Reflect.getOwnPropertyDescriptor(target,key);}});
 assert.deepEqual(bridge.translateOriginal92cbComplete(late),baseline,'primitive fields and whole geometry owned before later reflection');reject(`bank${bank}-late-reflection-reuse`,late);
 const detached=request(bank);structuredClone(detached.geometry.buffer,{transfer:[detached.geometry.buffer]});reject(`bank${bank}-detached`,detached);
 const symbol=request(bank);symbol[Symbol('hidden')]=0;reject(`bank${bank}-symbol-key`,symbol);
 const spoof=request(bank);spoof.geometry=Object.create(Uint8Array.prototype);reject(`bank${bank}-spoofed-typed-array`,spoof);
 const reentrant=request(bank);let nested=0;const wrapped=new Proxy(reentrant,{ownKeys(target){nested++;reject(`bank${bank}-reentrant-inner-${nested}`,null);return Reflect.ownKeys(target);}});assert.deepEqual(bridge.translateOriginal92cbComplete(wrapped),baseline);assert.equal(nested,2);
 for(const [key,value] of [['count',-1],['first',0xffffffff],['viewportWidth',1023],['viewportY',1],['samples',1],['mode',4],['colorFormat',0x8058]])reject(`bank${bank}-state-${key}`,{...request(bank),drawState:{...drawState,[key]:value}});
 for(const seed of seeds){let state=(seed^bank)>>>0;const next=()=>{state^=state<<13;state^=state>>>17;state^=state<<5;return state>>>0;};
  for(let i=0;i<24;i++){
   const altered=request(bank),at=next()%geometry.length;altered.geometry[at]^=1<<(next()%8);reject(`bank${bank}-geometry-${seed}-${i}`,altered);
   const name=i%2?'fragmentText':'vertexText',body=name==='fragmentText'?fragmentText:vertexText,position=next()%body.length;
   reject(`bank${bank}-source-${seed}-${i}`,{...request(bank),[name]:body.slice(0,position)+String.fromCharCode(body.charCodeAt(position)^1)+body.slice(position+1)});
  }
 }
 assert.deepEqual(bridge.translateOriginal92cbComplete(request(bank)),baseline,'every rejection preserves the next complete transaction');
}
console.log(JSON.stringify({status:'passed',seeds,cases:records.length,records,prefixRecords,ownedSnapshots:true,partialResults:false,productionDrawAuthority:false},null,2));
